  Lemma si_ld3f : forall (p b : Z) (y13 y14 y15 y16 y17 y6 : word),
    0 <= p -> p + 8 <= zlen bs -> 0 <= b < 2^30 ->
    (forall (z14 z15 z16 z6 : word),
       evt psegs POST (MS (mkR ra sp gp tp (Z_to_bv 64 (Z.land b 7)) z6 x7 x8 x9 x10 x11 (Z_to_bv 64 (S + p)) (Z_to_bv 64 S)
                               z14 z15 z16 (Z_to_bv 64 (le64v bs p)) x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                          F (Z_to_bv 64 0x1c208) fc None m (seg_rom psegs))) ->
    evt psegs POST (MS (mkR ra sp gp tp (Z_to_bv 64 b) y6 x7 x8 x9 x10 x11 (Z_to_bv 64 (S + p)) y13 y14 y15 y16 y17 x18 x19 x20
                            x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                       F (Z_to_bv 64 0x1c1a8) fc None m (seg_rom psegs)).
